using WF=System.Windows.Forms;

namespace PhotoTutor {
 internal static class CameraQualityChecks {
  const BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
  static T Field<T>(object value,string name)=>(T)value.GetType().GetField(name,Private)!.GetValue(value)!;
  static IEnumerable<WF.Control> All(WF.Control parent){foreach(WF.Control c in parent.Controls){yield return c;foreach(var n in All(c))yield return n;}}
  static void Pump(Func<bool> done,int milliseconds=12000){var t=Stopwatch.StartNew();while(t.ElapsedMilliseconds<milliseconds){WF.Application.DoEvents();if(done())return;Thread.Sleep(10);}throw new TimeoutException("Camera regression timed out");}
  static T Wait<T>(Task<T> task){Pump(()=>task.IsCompleted);return task.GetAwaiter().GetResult();}
  internal static BitmapSource Pattern(int w,int h,bool sharp){var b=new byte[w*h*3];for(int y=0;y<h;y++)for(int x=0;x<w;x++){byte v=sharp?(byte)((x/3+y/4)%2==0?230:50):(byte)140;int i=(y*w+x)*3;b[i]=b[i+1]=b[i+2]=v;}var image=BitmapSource.Create(w,h,96,96,PixelFormats.Bgr24,null,b,w*3);image.Freeze();return image;}
  static byte[] Pixels(BitmapSource source){var b=new FormatConvertedBitmap(source,PixelFormats.Bgr24,null,0);var bytes=new byte[b.PixelWidth*b.PixelHeight*3];b.CopyPixels(bytes,b.PixelWidth*3,0);return bytes;}
  sealed class FocusStub:IAMCameraControl {
   internal bool Auto=true,Throws;internal int Sets;internal CameraControlFlags Last;public int GetRange(CameraControlProperty p,out int min,out int max,out int step,out int value,out CameraControlFlags caps){min=0;max=100;step=1;value=40;caps=Auto?CameraControlFlags.Auto|CameraControlFlags.Manual:CameraControlFlags.Manual;if(Throws)throw new InvalidOperationException("synthetic driver error");return 0;}
   public int Set(CameraControlProperty p,int v,CameraControlFlags flags){Sets++;Last=flags;return 0;}
   public int Get(CameraControlProperty p,out int value,out CameraControlFlags flags){value=50;flags=CameraControlFlags.Manual;return 0;}
  }
  internal static int Run(string folder){Directory.CreateDirectory(folder);Settings.IsolatedTestRoot=Path.Combine(folder,"isolated-runtime");Entry.OfflineUiTesting=true;WF.Application.EnableVisualStyles();var rows=new List<object>();int failed=0;
   void Check(string name,Action test){try{test();rows.Add(new{name,passed=true});}catch(Exception e){failed++;rows.Add(new{name,passed=false,error=e.ToString()});}finally{CameraSession.DemoFrameForTest=null;CameraSession.EnumerateForTest=null;Entry.DemoCamera=false;}}
   Check("supported autofocus is enabled; fixed-focus and driver errors do not crash",()=>{var good=new FocusStub();if(!CameraFocus.Enable(good)||good.Sets!=1||good.Last!=CameraControlFlags.Auto)throw new Exception("Auto was not requested");var fixedFocus=new FocusStub{Auto=false};if(CameraFocus.Enable(fixedFocus)||fixedFocus.Sets!=0||CameraFocus.Enable(new FocusStub{Throws=true})||CameraFocus.Enable(null))throw new Exception("unsupported focus must be non-fatal");});
   Check("native mode chooses available source pixels without a 1920 target or aspect-ratio bias",()=>{var best=CameraMode.Choose(new[]{new CameraMode{Width=640,Height=480},new CameraMode{Width=1920,Height=1080},new CameraMode{Width=3840,Height=2160},new CameraMode{Width=1600,Height=1200}});if(best?.Width!=3840||CameraMode.Choose(new[]{new CameraMode{Width=1200,Height=768}})?.Height!=768||CameraMode.Safe(int.MaxValue,int.MaxValue))throw new Exception("mode selection lost native detail");});
   Check("only actual driver sample callbacks advance stream freshness",()=>{var pulse=new CameraSamplePulse();if(pulse.Sequence!=0)throw new Exception();pulse.BufferCB(1,IntPtr.Zero,0);long before=pulse.Sequence;Thread.Sleep(100);if(pulse.Sequence!=before)throw new Exception("a timer invented a new camera sample");pulse.BufferCB(2,IntPtr.Zero,0);if(pulse.Sequence!=before+1)throw new Exception("driver sample not observed");});
   Check("desktop branding migration is scoped to the existing product shortcut",()=>{string desktop=Path.Combine(folder,"test-desktop");Directory.CreateDirectory(desktop);string target=Path.Combine(desktop,"fixture.exe");File.WriteAllText(target,"inert test fixture");dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell")!);string old=Path.Combine(desktop,"拍照解题助教.lnk"),next=Path.Combine(desktop,"深度求索.lnk");dynamic link=shell.CreateShortcut(old);link.TargetPath=target;link.Save();ProductIdentity.MigrateDesktopName(desktop,target);if(!File.Exists(next)||File.Exists(old)||(string)shell.CreateShortcut(next).TargetPath!=target)throw new Exception("desktop shortcut migration failed");link=shell.CreateShortcut(old);link.TargetPath=Path.Combine(desktop,"unrelated.exe");link.Save();ProductIdentity.MigrateDesktopName(desktop,target);if(!File.Exists(old))throw new Exception("unrelated shortcut was removed");System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);});
   Check("capture waits for new stable frames and selects sharp pixels while preview keeps running",()=>{using(var buffer=new CaptureFrameBuffer()){var blur=Pattern(1200,768,false);var sharp=Pattern(1200,768,true);buffer.Publish(blur);int ticks=0;using(var timer=new WF.Timer{Interval=70}){timer.Tick+=(_,__)=>buffer.Publish(++ticks<3?blur:sharp);timer.Start();var photo=Wait(buffer.Capture(CancellationToken.None,250,1200));if(ticks<6||!ReferenceEquals(photo,sharp))throw new Exception("captured the first blur or blocked preview");timer.Stop();}}});
   Check("stalled preview cannot be photographed as a fresh image",()=>{using(var buffer=new CaptureFrameBuffer()){buffer.Publish(Pattern(400,300,true));try{Wait(buffer.Capture(CancellationToken.None,100,350));throw new Exception("stale frame was accepted");}catch(InvalidOperationException){}}});
   Check("cancel and closing the camera end an outstanding capture",()=>{using(var buffer=new CaptureFrameBuffer())using(var cancel=new CancellationTokenSource()){var task=buffer.Capture(cancel.Token,100,800);cancel.Cancel();try{Wait(task);throw new Exception("capture ignored cancellation");}catch(OperationCanceledException){}}using(var buffer=new CaptureFrameBuffer()){var task=buffer.Capture(CancellationToken.None,100,800);buffer.Dispose();try{Wait(task);throw new Exception("capture ignored disposal");}catch(OperationCanceledException){}}});
   Check("photo and submitted data are lossless PNG at original 3000-pixel width",()=>{var image=Pattern(3000,1000,true);var photo=PhotoData.Create(image,"fixture",false);if(photo.Image.PixelWidth!=3000||!photo.DataUri.StartsWith("data:image/png;base64,")||!Pixels(image).SequenceEqual(Pixels(photo.Image)))throw new Exception("photo shrunk before upload");using(var stream=new MemoryStream(photo.Jpeg)){var decoded=BitmapDecoder.Create(stream,BitmapCreateOptions.None,BitmapCacheOption.OnLoad).Frames[0];if(!Pixels(image).SequenceEqual(Pixels(decoded)))throw new Exception("lossy encoded pixels");}using(var preview=Raster.ToPreviewBitmap(image,640,480))if(preview.Width>640||photo.Image.PixelWidth!=3000)throw new Exception("preview sizing altered captured source");});
   Check("composed regions keep native crop pixels beyond the former 1600 limit",()=>{using(var workspace=new QuestionWorkspace(Settings.DataRoot)){var source=Pattern(3000,1200,true);var page=workspace.Add(source,"native fixture");var bounds=new Int32Rect(50,70,2800,800);workspace.Attach(workspace.AddRegion(page.Id,bounds).Id);var payload=workspace.Compose(false,CancellationToken.None);var composite=payload.Images.Single().Image;var actual=new CroppedBitmap(composite,new Int32Rect(0,38,bounds.Width,bounds.Height));if(composite.PixelWidth!=2800||!Pixels(actual).SequenceEqual(Pixels(new CroppedBitmap(source,bounds))))throw new Exception("composition resized or changed selected pixels");}});
   Check("clear and cancelling snapshot restore the real preview; duplicate F8 does not open two boards",()=>{Entry.DemoCamera=true;CameraSession.EnumerateForTest=()=>Array.Empty<CameraDevice>();var a=Pattern(1200,768,true);var b=Pattern(1200,768,false);int emitted=0;CameraSession.DemoFrameForTest=()=>Interlocked.Increment(ref emitted)%2==0?a:b;
    using(var main=new TutorForm()){main.ShowInTaskbar=false;main.StartPosition=WF.FormStartPosition.Manual;main.Location=new System.Drawing.Point(-12000,-12000);main.Show();Pump(()=>Field<BitmapSource?>(main,"live")!=null);if(!main.Text.StartsWith("深度求索 1.6.4")||All(main).OfType<WF.Button>().Any(x=>x.Text.Contains("原生展台")))throw new Exception("branding or removed entry wrong");
     All(main).OfType<WF.Button>().Single(x=>x.Text=="新对话／清空").PerformClick();Pump(()=>Field<BitmapSource?>(main,"live")!=null);int before=emitted;Pump(()=>emitted>=before+3);var snapshot=(Task)typeof(TutorForm).GetMethod("Snapshot",Private)!.Invoke(main,null)!;var duplicate=(Task)typeof(TutorForm).GetMethod("Snapshot",Private)!.Invoke(main,null)!;if(!duplicate.IsCompleted)throw new Exception("duplicate capture was started");Pump(()=>WF.Application.OpenForms.OfType<QuestionBoardDialog>().Any());var board=WF.Application.OpenForms.OfType<QuestionBoardDialog>().Single();board.Close();Pump(()=>snapshot.IsCompleted);snapshot.GetAwaiter().GetResult();Pump(()=>Field<BitmapSource?>(main,"live")!=null);before=emitted;Pump(()=>emitted>=before+3);using(var screenshot=new System.Drawing.Bitmap(main.Width,main.Height)){main.DrawToBitmap(screenshot,new System.Drawing.Rectangle(System.Drawing.Point.Empty,main.Size));screenshot.Save(Path.Combine(folder,"深度求索_恢复后的预览.png"));}main.Close();Pump(()=>!CameraSession.IsActive);}
   });
   Check("repeated focused capture releases the single camera session every time",()=>{for(int i=0;i<3;i++){using(var camera=new CameraSession("software",true,Pattern(1200,768,true))){Pump(()=>camera.HasFrame);var photo=Wait(camera.CaptureFocused(CancellationToken.None));if(photo.PixelWidth!=1200||photo.PixelHeight!=768)throw new Exception("source dimensions changed");}Pump(()=>!CameraSession.IsActive);}});
   Entry.OfflineUiTesting=false;File.WriteAllText(Path.Combine(folder,"对焦与无损拍照回归.json"),JsonConvert.SerializeObject(new{failed,checks=rows,physicalCameraVerified=false,paidCalls=0,sourcePixelsPreserved=true},Formatting.Indented));return failed==0?0:1;
  }
 }
}
